import { useMemo, useState } from "react";
import {
  AlertTriangle, Archive, ArrowRightLeft, Boxes, CheckCircle2, ClipboardList, FileClock,
  FileText, HandCoins, LoaderCircle, PackageCheck, Pill, Plus, ReceiptText, RefreshCw,
  ScanLine, ShieldCheck, ShoppingCart, Truck, WalletCards, X,
} from "lucide-react";
import { toast } from "sonner";
import { trpc } from "@/lib/trpc";

const TZS = new Intl.NumberFormat("en-TZ", { style: "currency", currency: "TZS", maximumFractionDigits: 0 });
const asList = (value) => (Array.isArray(value) ? value : []);
const asNumber = (value) => Number(value || 0);
const money = (value) => TZS.format(asNumber(value));
const dateTime = (value) => value ? new Date(value).toLocaleString("en-TZ", { dateStyle: "medium", timeStyle: "short" }) : "—";
const dateOnly = (value) => value ? new Date(`${value}T12:00:00`).toLocaleDateString("en-TZ", { dateStyle: "medium" }) : "—";
const errorMessage = (error, fallback = "The change could not be saved. Please check the details and try again.") => error?.message || fallback;

const EMPTY_MEDICINE = { name: "", genericName: "", categoryId: "__none__", brandId: "__none__", form: "Tablet", strength: "", barcode: "", sellingPrice: "", unitCost: "", reorderLevel: "0", requiresPrescription: false, controlled: false, taxRate: "0", notes: "" };
const EMPTY_SUPPLIER = { name: "", contactName: "", phone: "", email: "", address: "", paymentTermsDays: "30", notes: "" };
const EMPTY_RECEIPT_LINE = { drugId: "__none__", quantity: "", unitCost: "", batchNumber: "", expiryDate: "", barcode: "", warehouse: "Main pharmacy" };
const EMPTY_POS_LINE = { drugId: "__none__", quantity: "1" };
const EMPTY_DISPENSE_LINE = { drugId: "__none__", quantity: "1", instructions: "" };

function Panel({ title, description, children, className = "" }) {
  return <section className={`rounded-2xl border border-slate-200 bg-white p-5 shadow-sm ${className}`}><div className="mb-4"><h2 className="font-bold text-slate-900">{title}</h2>{description && <p className="mt-1 text-sm text-slate-500">{description}</p>}</div>{children}</section>;
}

function Empty({ children }) { return <p className="rounded-xl border border-dashed border-slate-200 bg-slate-50 p-4 text-sm text-slate-500">{children}</p>; }
function Field({ label, children, className = "" }) { return <label className={`grid gap-1.5 text-sm font-medium text-slate-700 ${className}`}><span>{label}</span>{children}</label>; }
function Input(props) { return <input {...props} className={`min-h-10 rounded-xl border border-slate-300 bg-white px-3 text-sm text-slate-900 outline-none transition focus:border-emerald-500 focus:ring-2 focus:ring-emerald-100 disabled:cursor-not-allowed disabled:bg-slate-100 ${props.className || ""}`} />; }
function Select(props) { return <select {...props} className={`min-h-10 rounded-xl border border-slate-300 bg-white px-3 text-sm text-slate-900 outline-none transition focus:border-emerald-500 focus:ring-2 focus:ring-emerald-100 disabled:cursor-not-allowed disabled:bg-slate-100 ${props.className || ""}`} />; }
function Textarea(props) { return <textarea {...props} className={`min-h-20 rounded-xl border border-slate-300 bg-white p-3 text-sm text-slate-900 outline-none transition focus:border-emerald-500 focus:ring-2 focus:ring-emerald-100 disabled:cursor-not-allowed disabled:bg-slate-100 ${props.className || ""}`} />; }
function Button({ children, variant = "primary", className = "", ...props }) {
  const colors = variant === "primary" ? "bg-emerald-700 text-white hover:bg-emerald-800" : variant === "danger" ? "bg-rose-600 text-white hover:bg-rose-700" : "border border-slate-300 bg-white text-slate-700 hover:bg-slate-50";
  return <button {...props} className={`inline-flex min-h-10 items-center justify-center gap-2 rounded-xl px-3 text-sm font-semibold transition active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-50 ${colors} ${className}`}>{children}</button>;
}
function Status({ value }) { const text = String(value || "Unknown"); const color = /paid|active|received|dispensed|recorded|restocked|submitted/i.test(text) ? "bg-emerald-50 text-emerald-700" : /expired|archived|damaged|quarantined/i.test(text) ? "bg-rose-50 text-rose-700" : "bg-amber-50 text-amber-800"; return <span className={`inline-flex rounded-full px-2.5 py-1 text-xs font-semibold ${color}`}>{text}</span>; }
function SectionDenied({ children }) { return <div className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900"><strong>Restricted action.</strong> {children}</div>; }
function TableWrap({ children }) { return <div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-sm">{children}</table></div>; }
function LoadingRows() { return <div className="flex items-center gap-2 py-4 text-sm text-slate-500"><LoaderCircle size={16} className="animate-spin" /> Loading secure records…</div>; }

export function PharmacyWorkspace({ onNavigate }) {
  const [tab, setTab] = useState("Overview");
  const [medicineSearch, setMedicineSearch] = useState("");
  const [medicineForm, setMedicineForm] = useState(EMPTY_MEDICINE);
  const [editingMedicineId, setEditingMedicineId] = useState(null);
  const [supplierForm, setSupplierForm] = useState(EMPTY_SUPPLIER);
  const [editingSupplierId, setEditingSupplierId] = useState(null);
  const [categoryName, setCategoryName] = useState("");
  const [brandForm, setBrandForm] = useState({ name: "", manufacturer: "" });
  const [poForm, setPoForm] = useState({ supplierId: "__none__", expectedDate: "", notes: "" });
  const [poLines, setPoLines] = useState([{ drugId: "__none__", quantity: "", unitCost: "", taxRate: "0" }]);
  const [receiptForm, setReceiptForm] = useState({ purchaseOrderId: "__none__", supplierId: "__none__", invoiceReference: "", notes: "" });
  const [receiptLines, setReceiptLines] = useState([EMPTY_RECEIPT_LINE]);
  const [adjustmentForm, setAdjustmentForm] = useState({ batchId: "__none__", quantityDelta: "", reason: "", notes: "" });
  const [transferForm, setTransferForm] = useState({ batchId: "__none__", quantity: "", fromLocation: "Main pharmacy", toLocation: "", notes: "" });
  const [dispenseForm, setDispenseForm] = useState({ prescriptionId: "__manual__", patientId: "__none__", prescriberName: "", prescriberLicense: "", notes: "" });
  const [dispenseLines, setDispenseLines] = useState([EMPTY_DISPENSE_LINE]);
  const [saleForm, setSaleForm] = useState({ patientId: "__none__", customerName: "", paymentMethod: "Cash", insuranceProvider: "", discount: "0", notes: "" });
  const [saleLines, setSaleLines] = useState([EMPTY_POS_LINE]);
  const [salePayment, setSalePayment] = useState({ saleId: "__none__", amount: "", method: "Cash", insuranceProvider: "", reference: "", notes: "" });
  const [supplierPayment, setSupplierPayment] = useState({ supplierId: "__none__", amount: "", method: "Bank transfer", reference: "", notes: "" });
  const [insuranceClaim, setInsuranceClaim] = useState({ saleId: "__none__", provider: "", memberReference: "", amount: "", notes: "" });
  const [returnForm, setReturnForm] = useState({ saleId: "__none__", reason: "", condition: "Sealed and resellable", notes: "" });
  const [returnLines, setReturnLines] = useState([]);

  const utils = trpc.useUtils();
  const inputs = useMemo(() => ({ drugs: { table: "phm_drugs", limit: 250 }, categories: { table: "phm_categories", limit: 250 }, brands: { table: "phm_brands", limit: 250 }, suppliers: { table: "phm_suppliers", limit: 250 }, orders: { table: "phm_purchase_orders", limit: 250 }, batches: { table: "phm_batches", limit: 500 }, movements: { table: "phm_stock_movements", limit: 250 }, transfers: { table: "phm_stock_transfers", limit: 250 }, dispenses: { table: "phm_dispense", limit: 250 }, controlled: { table: "phm_controlled_medicine_register", limit: 250 }, sales: { table: "phm_sales", limit: 250 }, saleItems: { table: "phm_sale_items", limit: 500 }, claims: { table: "phm_insurance_claims", limit: 250 }, returns: { table: "phm_returns", limit: 250 }, audit: { table: "phm_audit_logs", limit: 250 }, clinical: { limit: 150 } }), []);
  const dashboard = trpc.pharmacy.dashboard.useQuery(undefined, { retry: false });
  const accessQuery = trpc.pharmacy.access.useQuery(undefined, { retry: false });
  const medicinesQuery = trpc.pharmacy.list.useQuery(inputs.drugs, { enabled: ["Catalog", "Purchasing", "Stock", "Dispensing", "POS"].includes(tab), retry: false });
  const categoriesQuery = trpc.pharmacy.list.useQuery(inputs.categories, { enabled: tab === "Catalog", retry: false });
  const brandsQuery = trpc.pharmacy.list.useQuery(inputs.brands, { enabled: tab === "Catalog", retry: false });
  const suppliersQuery = trpc.pharmacy.list.useQuery(inputs.suppliers, { enabled: ["Suppliers", "Purchasing", "Reports"].includes(tab), retry: false });
  const ordersQuery = trpc.pharmacy.list.useQuery(inputs.orders, { enabled: tab === "Purchasing", retry: false });
  const batchesQuery = trpc.pharmacy.list.useQuery(inputs.batches, { enabled: ["Stock", "Purchasing"].includes(tab), retry: false });
  const movementsQuery = trpc.pharmacy.list.useQuery(inputs.movements, { enabled: tab === "Stock", retry: false });
  const transfersQuery = trpc.pharmacy.list.useQuery(inputs.transfers, { enabled: tab === "Stock", retry: false });
  const dispensesQuery = trpc.pharmacy.list.useQuery(inputs.dispenses, { enabled: tab === "Dispensing", retry: false });
  const controlledQuery = trpc.pharmacy.list.useQuery(inputs.controlled, { enabled: ["Dispensing", "Reports"].includes(tab), retry: false });
  const salesQuery = trpc.pharmacy.list.useQuery(inputs.sales, { enabled: tab === "POS", retry: false });
  const saleItemsQuery = trpc.pharmacy.list.useQuery(inputs.saleItems, { enabled: tab === "POS", retry: false });
  const claimsQuery = trpc.pharmacy.list.useQuery(inputs.claims, { enabled: ["POS", "Reports"].includes(tab), retry: false });
  const returnsQuery = trpc.pharmacy.list.useQuery(inputs.returns, { enabled: ["POS", "Reports"].includes(tab), retry: false });
  const clinicalQuery = trpc.pharmacy.clinicalQueue.useQuery(inputs.clinical, { enabled: tab === "Dispensing", retry: false });
  const reportsQuery = trpc.pharmacy.reports.useQuery(undefined, { enabled: tab === "Reports", retry: false });
  const auditQuery = trpc.pharmacy.audit.useQuery(inputs.audit, { enabled: tab === "Reports", retry: false });

  const createCategory = trpc.pharmacy.createCategory.useMutation();
  const createBrand = trpc.pharmacy.createBrand.useMutation();
  const createMedicine = trpc.pharmacy.createMedicine.useMutation();
  const updateMedicine = trpc.pharmacy.updateMedicine.useMutation();
  const createSupplier = trpc.pharmacy.createSupplier.useMutation();
  const updateSupplier = trpc.pharmacy.updateSupplier.useMutation();
  const archiveRecord = trpc.pharmacy.archive.useMutation();
  const createPurchaseOrder = trpc.pharmacy.createPurchaseOrder.useMutation();
  const receiveStock = trpc.pharmacy.receiveStock.useMutation();
  const adjustStock = trpc.pharmacy.adjustStock.useMutation();
  const createTransfer = trpc.pharmacy.createStockTransfer.useMutation();
  const dispensePrescription = trpc.pharmacy.dispensePrescription.useMutation();
  const completeSale = trpc.pharmacy.completeSale.useMutation();
  const recordSalePayment = trpc.pharmacy.recordSalePayment.useMutation();
  const recordSupplierPayment = trpc.pharmacy.recordSupplierPayment.useMutation();
  const createInsuranceClaim = trpc.pharmacy.createInsuranceClaim.useMutation();
  const returnSaleItems = trpc.pharmacy.returnSaleItems.useMutation();
  const markNotificationRead = trpc.pharmacy.markNotificationRead.useMutation();

  const medicines = asList(medicinesQuery.data?.records);
  const categories = asList(categoriesQuery.data?.records);
  const brands = asList(brandsQuery.data?.records);
  const suppliers = asList(suppliersQuery.data?.records);
  const orders = asList(ordersQuery.data?.records);
  const batches = asList(batchesQuery.data?.records);
  const movements = asList(movementsQuery.data?.records);
  const transfers = asList(transfersQuery.data?.records);
  const dispenses = asList(dispensesQuery.data?.records);
  const controlled = asList(controlledQuery.data?.records);
  const sales = asList(salesQuery.data?.records);
  const saleItems = asList(saleItemsQuery.data?.records);
  const claims = asList(claimsQuery.data?.records);
  const returns = asList(returnsQuery.data?.records);
  const clinical = clinicalQuery.data || { patients: [], prescriptions: [] };
  const filteredMedicines = medicines.filter((record) => !medicineSearch || JSON.stringify(record).toLowerCase().includes(medicineSearch.toLowerCase()));
  const selectedReturnItems = returnForm.saleId === "__none__" ? [] : saleItems.filter((item) => item.saleId === returnForm.saleId && asNumber(item.quantity) > asNumber(item.returnedQuantity));
  const access = dashboard.data?.access || accessQuery.data || {};
  const has = (key) => Boolean(access[key]);

  async function refresh() {
    await Promise.all([utils.pharmacy.dashboard.invalidate(), utils.pharmacy.list.invalidate(), utils.pharmacy.clinicalQueue.invalidate(), utils.pharmacy.reports.invalidate(), utils.pharmacy.audit.invalidate()]);
  }
  async function run(action, success) { try { await action(); toast.success(success); await refresh(); } catch (error) { toast.error(errorMessage(error)); } }
  function resetMedicine() { setMedicineForm(EMPTY_MEDICINE); setEditingMedicineId(null); }
  function startMedicineEdit(record) { setEditingMedicineId(record.id); setMedicineForm({ name: record.name || "", genericName: record.genericName || "", categoryId: record.categoryId || "__none__", brandId: record.brandId || "__none__", form: record.form || "Tablet", strength: record.strength || "", barcode: record.barcode || "", sellingPrice: String(record.sellingPrice ?? record.amount ?? ""), unitCost: String(record.unitCost ?? ""), reorderLevel: String(record.reorderLevel ?? 0), requiresPrescription: Boolean(record.requiresPrescription), controlled: Boolean(record.controlled), taxRate: String(record.taxRate ?? 0), notes: record.notes || "" }); }
  function startSupplierEdit(record) { setEditingSupplierId(record.id); setSupplierForm({ name: record.name || "", contactName: record.contactName || "", phone: record.phone || "", email: record.email || "", address: record.address || "", paymentTermsDays: String(record.paymentTermsDays ?? 30), notes: record.notes || "" }); }
  function confirmArchive(table, record) { if (!window.confirm(`Archive ${record.name}? This preserves its audit history and cannot remove stock records.`)) return; run(() => archiveRecord.mutateAsync({ table, id: record.id, reason: "Archived from Pharmacy Command Center" }), `${record.name} was archived.`); }
  function choosePrescription(id) { const prescription = asList(clinical.prescriptions).find((item) => item.id === id); setDispenseForm((current) => ({ ...current, prescriptionId: id, patientId: prescription?.patientId || "__none__", prescriberName: prescription?.doctorName || current.prescriberName, notes: prescription?.instructions || current.notes })); }

  if (dashboard.isLoading) return <div className="grid min-h-72 place-items-center rounded-2xl border bg-white"><LoaderCircle className="animate-spin text-emerald-600" /></div>;
  const pharmacyErrorMessage = String(dashboard.error?.message || "");
  const pharmacyAccessDenied = dashboard.error?.data?.code === "FORBIDDEN" || /access|role|assigned|permission|allow this action/i.test(pharmacyErrorMessage);
  if (dashboard.error) return <div role="alert" className="rounded-2xl border border-rose-200 bg-rose-50 p-5 text-sm text-rose-800"><strong>{pharmacyAccessDenied ? "Pharmacy access is restricted." : "Pharmacy data is temporarily unavailable."}</strong><p className="mt-1">{pharmacyAccessDenied ? "Your profile is not assigned a Pharmacy Management role for this workspace. No records were changed." : `No records were changed. ${pharmacyErrorMessage || "The server-confirmed pharmacy snapshot could not be read."}`}</p>{!pharmacyAccessDenied && <button type="button" onClick={() => dashboard.refetch()} className="mt-3 inline-flex items-center gap-2 rounded-xl border border-rose-200 bg-white px-3 py-2 text-xs font-bold text-rose-800 hover:bg-rose-50"><RefreshCw size={14} /> Retry read</button>}</div>;
  const data = dashboard.data;
  const cards = [["Medicines", data.totals.medicines, Pill], ["Stock value", money(data.totals.stockValue), Boxes], ["Low stock", data.totals.lowStock, AlertTriangle], ["Today’s sales", money(data.totals.todaySales), ReceiptText]];
  const tabs = [["Overview", ClipboardList], ["Catalog", Pill], ["Suppliers", Truck], ["Purchasing", ShoppingCart], ["Stock", Boxes], ["Dispensing", ScanLine], ["POS", WalletCards], ["Reports", FileText], ["Alerts & audit", ShieldCheck]];

  return <div className="space-y-5">
    <section className="rounded-3xl bg-gradient-to-br from-emerald-950 via-emerald-800 to-teal-600 p-6 text-white shadow-lg"><div className="flex flex-col justify-between gap-5 lg:flex-row lg:items-center"><div className="flex items-start gap-3"><span className="grid h-12 w-12 shrink-0 place-items-center rounded-2xl bg-white/15"><Pill /></span><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-emerald-100">Clinical inventory and dispensary</p><h1 className="mt-1 text-2xl font-bold">Pharmacy Command Center</h1><p className="mt-2 max-w-2xl text-sm text-emerald-50">Tenant-scoped catalog, FEFO batch stock, clinical dispensing, retail sales, controlled-medicine records, and Tanzania-ready settlements.</p></div></div><Button variant="secondary" onClick={() => refresh()}><RefreshCw size={16} /> Refresh records</Button></div></section>

    <nav className="flex gap-2 overflow-x-auto rounded-2xl border border-slate-200 bg-white p-2" aria-label="Pharmacy workspace sections">{tabs.map(([label, Icon]) => <button key={label} onClick={() => setTab(label)} className={`inline-flex shrink-0 items-center gap-2 rounded-xl px-3 py-2 text-sm font-semibold transition ${tab === label ? "bg-emerald-700 text-white shadow-sm" : "text-slate-600 hover:bg-slate-100"}`}><Icon size={16} />{label}</button>)}</nav>

    {tab === "Overview" && <div className="space-y-5"><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{cards.map(([label, value, Icon]) => <article key={label} className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><Icon className="text-emerald-600" size={19} /><p className="mt-3 text-2xl font-bold text-slate-900">{value}</p><p className="text-xs font-semibold text-slate-500">{label}</p></article>)}</section><section className="grid gap-4 lg:grid-cols-2"><Panel title="Low-stock attention" description="Reorder thresholds are evaluated against available medicine quantity.">{data.lowStock.length ? <div className="space-y-3">{data.lowStock.map((record) => <div key={record.id} className="flex items-center justify-between rounded-xl bg-amber-50 p-3"><div><p className="font-semibold text-slate-900">{record.name}</p><p className="text-xs text-slate-600">{asNumber(record.availableQuantity)} on hand · reorder at {asNumber(record.reorderLevel)}</p></div><Status value="Review" /></div>)}</div> : <Empty>No low-stock medicines need attention.</Empty>}</Panel><Panel title="Expiry queue" description="FEFO allocation excludes expired batches and uses the earliest eligible expiry first.">{data.expiring.length ? <div className="space-y-3">{data.expiring.map((record) => <div key={record.id} className="flex items-center justify-between rounded-xl bg-rose-50 p-3"><div><p className="font-semibold text-slate-900">{record.drugName || record.name}</p><p className="text-xs text-slate-600">Batch {record.batchNumber || "—"} · expires {dateOnly(record.expiryDate)}</p></div><Status value={record.status} /></div>)}</div> : <Empty>No active batches expire within 90 days.</Empty>}</Panel></section><Panel title="Operating safeguards" description="The Pharmacy workspace enforces clinical, stock, and financial boundaries before any record is committed."><div className="grid gap-3 md:grid-cols-3"><div className="rounded-xl bg-emerald-50 p-4 text-sm text-emerald-900"><PackageCheck size={18} className="mb-2" /><strong>FEFO dispensing</strong><br />Expired or insufficient batches are rejected before dispensing or sale.</div><div className="rounded-xl bg-indigo-50 p-4 text-sm text-indigo-900"><ShieldCheck size={18} className="mb-2" /><strong>Controlled medicines</strong><br />Only pharmacists and pharmacy administrators can issue controlled stock.</div><div className="rounded-xl bg-amber-50 p-4 text-sm text-amber-900"><HandCoins size={18} className="mb-2" /><strong>TZS settlements</strong><br />Sales, supplier balances, insurance claims, and receipts remain tenant scoped.</div></div><div className="mt-4 flex flex-wrap gap-2"><Button variant="secondary" onClick={() => onNavigate?.("healthcare")}>Open Healthcare</Button><Button variant="secondary" onClick={() => onNavigate?.("inventory")}>Open Inventory</Button><Button variant="secondary" onClick={() => onNavigate?.("finance")}>Open Finance</Button></div></Panel></div>}

    {tab === "Catalog" && <div className="space-y-5"><section className="grid gap-4 xl:grid-cols-3"><Panel title={editingMedicineId ? "Edit medicine" : "Add medicine"} description="Barcode, pricing, tax, prescription, controlled-medicine, and reorder rules are verified on save." className="xl:col-span-2">{!has("canCatalog") ? <SectionDenied>Your role can view the catalogue but cannot change medicines or reference data.</SectionDenied> : <form className="grid gap-3 md:grid-cols-2" onSubmit={(event) => { event.preventDefault(); const payload = { name: medicineForm.name, genericName: medicineForm.genericName, categoryId: medicineForm.categoryId === "__none__" ? undefined : medicineForm.categoryId, brandId: medicineForm.brandId === "__none__" ? undefined : medicineForm.brandId, form: medicineForm.form, strength: medicineForm.strength, barcode: medicineForm.barcode, sellingPrice: asNumber(medicineForm.sellingPrice), unitCost: asNumber(medicineForm.unitCost), reorderLevel: asNumber(medicineForm.reorderLevel), requiresPrescription: medicineForm.requiresPrescription, controlled: medicineForm.controlled, taxRate: asNumber(medicineForm.taxRate), notes: medicineForm.notes }; run(() => editingMedicineId ? updateMedicine.mutateAsync({ id: editingMedicineId, ...payload }) : createMedicine.mutateAsync(payload), editingMedicineId ? "Medicine updated." : "Medicine added to the catalogue."); resetMedicine(); }}><Field label="Medicine name"><Input required value={medicineForm.name} onChange={(event) => setMedicineForm({ ...medicineForm, name: event.target.value })} /></Field><Field label="Generic name"><Input value={medicineForm.genericName} onChange={(event) => setMedicineForm({ ...medicineForm, genericName: event.target.value })} /></Field><Field label="Category"><Select value={medicineForm.categoryId} onChange={(event) => setMedicineForm({ ...medicineForm, categoryId: event.target.value })}><option value="__none__">No category</option>{categories.map((record) => <option key={record.id} value={record.id}>{record.name}</option>)}</Select></Field><Field label="Brand"><Select value={medicineForm.brandId} onChange={(event) => setMedicineForm({ ...medicineForm, brandId: event.target.value })}><option value="__none__">No brand</option>{brands.map((record) => <option key={record.id} value={record.id}>{record.name}</option>)}</Select></Field><Field label="Dosage form"><Input required value={medicineForm.form} onChange={(event) => setMedicineForm({ ...medicineForm, form: event.target.value })} /></Field><Field label="Strength"><Input value={medicineForm.strength} onChange={(event) => setMedicineForm({ ...medicineForm, strength: event.target.value })} placeholder="e.g. 500 mg" /></Field><Field label="Barcode"><Input value={medicineForm.barcode} onChange={(event) => setMedicineForm({ ...medicineForm, barcode: event.target.value })} placeholder="Scan or enter barcode" /></Field><Field label="Selling price (TZS)"><Input required min="0" type="number" value={medicineForm.sellingPrice} onChange={(event) => setMedicineForm({ ...medicineForm, sellingPrice: event.target.value })} /></Field><Field label="Unit cost (TZS)"><Input required min="0" type="number" value={medicineForm.unitCost} onChange={(event) => setMedicineForm({ ...medicineForm, unitCost: event.target.value })} /></Field><Field label="Reorder level"><Input required min="0" type="number" value={medicineForm.reorderLevel} onChange={(event) => setMedicineForm({ ...medicineForm, reorderLevel: event.target.value })} /></Field><Field label="Tax rate (%)"><Input required min="0" max="100" type="number" value={medicineForm.taxRate} onChange={(event) => setMedicineForm({ ...medicineForm, taxRate: event.target.value })} /></Field><Field label="Notes"><Input value={medicineForm.notes} onChange={(event) => setMedicineForm({ ...medicineForm, notes: event.target.value })} /></Field><div className="md:col-span-2 flex flex-wrap gap-4 rounded-xl bg-slate-50 p-3"><label className="inline-flex items-center gap-2 text-sm font-semibold text-slate-700"><input type="checkbox" checked={medicineForm.requiresPrescription} onChange={(event) => setMedicineForm({ ...medicineForm, requiresPrescription: event.target.checked })} /> Prescription only</label><label className="inline-flex items-center gap-2 text-sm font-semibold text-slate-700"><input type="checkbox" checked={medicineForm.controlled} onChange={(event) => setMedicineForm({ ...medicineForm, controlled: event.target.checked })} /> Controlled medicine</label></div><div className="md:col-span-2 flex gap-2"><Button type="submit" disabled={createMedicine.isPending || updateMedicine.isPending}><Pill size={16} />{editingMedicineId ? "Save medicine" : "Add medicine"}</Button>{editingMedicineId && <Button type="button" variant="secondary" onClick={resetMedicine}>Cancel edit</Button>}</div></form>}</Panel><div className="space-y-4"><Panel title="Category" description="Reference taxonomy for clinical stock.">{has("canCatalog") ? <form className="flex gap-2" onSubmit={(event) => { event.preventDefault(); run(() => createCategory.mutateAsync({ name: categoryName, notes: "" }), "Category added."); setCategoryName(""); }}><Input required value={categoryName} onChange={(event) => setCategoryName(event.target.value)} placeholder="e.g. Antibiotics" /><Button type="submit" disabled={createCategory.isPending}><Plus size={16} /></Button></form> : <SectionDenied>Catalogue reference maintenance is restricted.</SectionDenied>}</Panel><Panel title="Brand" description="Manufacturer identity used by catalogue and procurement.">{has("canCatalog") ? <form className="grid gap-2" onSubmit={(event) => { event.preventDefault(); run(() => createBrand.mutateAsync({ ...brandForm, notes: "" }), "Brand added."); setBrandForm({ name: "", manufacturer: "" }); }}><Input required value={brandForm.name} onChange={(event) => setBrandForm({ ...brandForm, name: event.target.value })} placeholder="Brand name" /><Input value={brandForm.manufacturer} onChange={(event) => setBrandForm({ ...brandForm, manufacturer: event.target.value })} placeholder="Manufacturer" /><Button type="submit" disabled={createBrand.isPending}><Plus size={16} /> Add brand</Button></form> : <SectionDenied>Catalogue reference maintenance is restricted.</SectionDenied>}</Panel></div></section><Panel title="Medicine catalogue" description="Search catalogue records, then open a real edit or archive operation."><div className="mb-4 flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between"><Input className="max-w-md" value={medicineSearch} onChange={(event) => setMedicineSearch(event.target.value)} placeholder="Search name, generic, barcode, or dosage form" /><span className="text-sm text-slate-500">{filteredMedicines.length} visible medicines</span></div>{medicinesQuery.isLoading ? <LoadingRows /> : filteredMedicines.length ? <TableWrap><thead className="border-b text-xs uppercase tracking-wide text-slate-500"><tr><th className="pb-3 pr-3">Medicine</th><th className="pb-3 pr-3">Barcode / form</th><th className="pb-3 pr-3">Price</th><th className="pb-3 pr-3">On hand</th><th className="pb-3 pr-3">Clinical rule</th><th className="pb-3">Action</th></tr></thead><tbody>{filteredMedicines.map((record) => <tr key={record.id} className="border-b border-slate-100"><td className="py-3 pr-3"><p className="font-semibold text-slate-900">{record.name}</p><p className="text-xs text-slate-500">{record.genericName || "No generic name"}</p></td><td className="py-3 pr-3 text-slate-600">{record.barcode || "—"}<br /><span className="text-xs">{record.form} {record.strength}</span></td><td className="py-3 pr-3 font-semibold text-slate-900">{money(record.sellingPrice || record.amount)}</td><td className="py-3 pr-3">{asNumber(record.availableQuantity)}</td><td className="py-3 pr-3"><div className="flex flex-wrap gap-1">{record.requiresPrescription && <Status value="Rx" />}{record.controlled && <Status value="Controlled" />}{!record.requiresPrescription && !record.controlled && <span className="text-slate-500">Counter eligible</span>}</div></td><td className="py-3"><div className="flex gap-2">{has("canCatalog") && <Button variant="secondary" onClick={() => startMedicineEdit(record)}>Edit</Button>}{has("canCatalog") && <Button variant="secondary" onClick={() => confirmArchive("phm_drugs", record)}><Archive size={15} /></Button>}</div></td></tr>)}</tbody></TableWrap> : <Empty>No medicine matches this search.</Empty>}</Panel></div>}

    {tab === "Suppliers" && <div className="grid gap-5 xl:grid-cols-[0.9fr_1.4fr]"><div className="space-y-5"><Panel title={editingSupplierId ? "Edit supplier" : "Add supplier"} description="Supplier outstanding balances update automatically when goods are received or settled.">{!has("canPurchase") ? <SectionDenied>Your role can view supplier records but cannot maintain suppliers.</SectionDenied> : <form className="grid gap-3" onSubmit={(event) => { event.preventDefault(); const payload = { ...supplierForm, paymentTermsDays: asNumber(supplierForm.paymentTermsDays) }; run(() => editingSupplierId ? updateSupplier.mutateAsync({ id: editingSupplierId, ...payload }) : createSupplier.mutateAsync(payload), editingSupplierId ? "Supplier updated." : "Supplier added."); setSupplierForm(EMPTY_SUPPLIER); setEditingSupplierId(null); }}><Field label="Supplier name"><Input required value={supplierForm.name} onChange={(event) => setSupplierForm({ ...supplierForm, name: event.target.value })} /></Field><Field label="Contact name"><Input value={supplierForm.contactName} onChange={(event) => setSupplierForm({ ...supplierForm, contactName: event.target.value })} /></Field><Field label="Phone"><Input value={supplierForm.phone} onChange={(event) => setSupplierForm({ ...supplierForm, phone: event.target.value })} /></Field><Field label="Email"><Input type="email" value={supplierForm.email} onChange={(event) => setSupplierForm({ ...supplierForm, email: event.target.value })} /></Field><Field label="Address"><Input value={supplierForm.address} onChange={(event) => setSupplierForm({ ...supplierForm, address: event.target.value })} /></Field><Field label="Payment terms (days)"><Input min="0" max="365" type="number" value={supplierForm.paymentTermsDays} onChange={(event) => setSupplierForm({ ...supplierForm, paymentTermsDays: event.target.value })} /></Field><Field label="Notes"><Textarea value={supplierForm.notes} onChange={(event) => setSupplierForm({ ...supplierForm, notes: event.target.value })} /></Field><div className="flex gap-2"><Button type="submit" disabled={createSupplier.isPending || updateSupplier.isPending}><Truck size={16} />{editingSupplierId ? "Save supplier" : "Add supplier"}</Button>{editingSupplierId && <Button type="button" variant="secondary" onClick={() => { setSupplierForm(EMPTY_SUPPLIER); setEditingSupplierId(null); }}>Cancel</Button>}</div></form>}</Panel><Panel title="Settle supplier balance" description="Settlement cannot exceed the currently recorded payable.">{!has("canFinance") ? <SectionDenied>Supplier settlement is limited to pharmacy finance roles.</SectionDenied> : <form className="grid gap-3" onSubmit={(event) => { event.preventDefault(); run(() => recordSupplierPayment.mutateAsync({ ...supplierPayment, supplierId: supplierPayment.supplierId, amount: asNumber(supplierPayment.amount) }), "Supplier settlement recorded."); setSupplierPayment({ supplierId: "__none__", amount: "", method: "Bank transfer", reference: "", notes: "" }); }}><Field label="Supplier"><Select required value={supplierPayment.supplierId} onChange={(event) => setSupplierPayment({ ...supplierPayment, supplierId: event.target.value })}><option value="__none__">Select supplier</option>{suppliers.map((record) => <option key={record.id} value={record.id}>{record.name} · {money(record.outstandingBalance)}</option>)}</Select></Field><Field label="Amount (TZS)"><Input required min="1" type="number" value={supplierPayment.amount} onChange={(event) => setSupplierPayment({ ...supplierPayment, amount: event.target.value })} /></Field><Field label="Method"><Select value={supplierPayment.method} onChange={(event) => setSupplierPayment({ ...supplierPayment, method: event.target.value })}>{["Cash", "Mobile money", "Card", "Bank transfer"].map((value) => <option key={value}>{value}</option>)}</Select></Field><Field label="Reference"><Input value={supplierPayment.reference} onChange={(event) => setSupplierPayment({ ...supplierPayment, reference: event.target.value })} /></Field><Button type="submit" disabled={recordSupplierPayment.isPending}><HandCoins size={16} /> Record settlement</Button></form>}</Panel></div><Panel title="Supplier ledger" description="Outstanding balances arise from approved stock receipts and can only decrease through a settlement record.">{suppliersQuery.isLoading ? <LoadingRows /> : suppliers.length ? <TableWrap><thead className="border-b text-xs uppercase tracking-wide text-slate-500"><tr><th className="pb-3 pr-3">Supplier</th><th className="pb-3 pr-3">Contact</th><th className="pb-3 pr-3">Terms</th><th className="pb-3 pr-3">Outstanding</th><th className="pb-3">Action</th></tr></thead><tbody>{suppliers.map((record) => <tr key={record.id} className="border-b border-slate-100"><td className="py-3 pr-3"><p className="font-semibold text-slate-900">{record.name}</p><p className="text-xs text-slate-500">{record.address || "No address"}</p></td><td className="py-3 pr-3 text-slate-600">{record.contactName || "—"}<br /><span className="text-xs">{record.phone || record.email || "—"}</span></td><td className="py-3 pr-3">{asNumber(record.paymentTermsDays)} days</td><td className="py-3 pr-3 font-semibold text-slate-900">{money(record.outstandingBalance)}</td><td className="py-3"><div className="flex gap-2">{has("canPurchase") && <Button variant="secondary" onClick={() => startSupplierEdit(record)}>Edit</Button>}{has("canPurchase") && <Button variant="secondary" onClick={() => confirmArchive("phm_suppliers", record)}><Archive size={15} /></Button>}</div></td></tr>)}</tbody></TableWrap> : <Empty>No supplier records yet. Create a supplier before drafting a purchase order.</Empty>}</Panel></div>}

    {tab === "Purchasing" && <div className="space-y-5"><section className="grid gap-5 xl:grid-cols-2"><Panel title="Create purchase order" description="Purchase-order line totals and applicable TZS tax are calculated on the protected server.">{!has("canPurchase") ? <SectionDenied>Your role cannot create purchase orders.</SectionDenied> : <form className="space-y-3" onSubmit={(event) => { event.preventDefault(); run(() => createPurchaseOrder.mutateAsync({ supplierId: poForm.supplierId, expectedDate: poForm.expectedDate ? new Date(`${poForm.expectedDate}T00:00:00`).toISOString() : undefined, notes: poForm.notes, items: poLines.map((line) => ({ drugId: line.drugId, quantity: asNumber(line.quantity), unitCost: asNumber(line.unitCost), taxRate: asNumber(line.taxRate) })) }), "Purchase order created."); setPoForm({ supplierId: "__none__", expectedDate: "", notes: "" }); setPoLines([{ drugId: "__none__", quantity: "", unitCost: "", taxRate: "0" }]); }}><div className="grid gap-3 md:grid-cols-2"><Field label="Supplier"><Select required value={poForm.supplierId} onChange={(event) => setPoForm({ ...poForm, supplierId: event.target.value })}><option value="__none__">Select supplier</option>{suppliers.map((record) => <option key={record.id} value={record.id}>{record.name}</option>)}</Select></Field><Field label="Expected delivery"><Input type="date" value={poForm.expectedDate} onChange={(event) => setPoForm({ ...poForm, expectedDate: event.target.value })} /></Field></div><div className="space-y-2">{poLines.map((line, index) => <div key={index} className="grid gap-2 rounded-xl bg-slate-50 p-3 md:grid-cols-[1.8fr_0.7fr_0.9fr_0.7fr_auto]"><Select required value={line.drugId} onChange={(event) => setPoLines(poLines.map((item, itemIndex) => itemIndex === index ? { ...item, drugId: event.target.value } : item))}><option value="__none__">Medicine</option>{medicines.map((record) => <option key={record.id} value={record.id}>{record.name}</option>)}</Select><Input required min="0.0001" type="number" value={line.quantity} onChange={(event) => setPoLines(poLines.map((item, itemIndex) => itemIndex === index ? { ...item, quantity: event.target.value } : item))} placeholder="Qty" /><Input required min="0" type="number" value={line.unitCost} onChange={(event) => setPoLines(poLines.map((item, itemIndex) => itemIndex === index ? { ...item, unitCost: event.target.value } : item))} placeholder="Cost" /><Input required min="0" max="100" type="number" value={line.taxRate} onChange={(event) => setPoLines(poLines.map((item, itemIndex) => itemIndex === index ? { ...item, taxRate: event.target.value } : item))} placeholder="Tax %" />{poLines.length > 1 && <Button type="button" variant="secondary" onClick={() => setPoLines(poLines.filter((_, itemIndex) => itemIndex !== index))}><X size={16} /></Button>}</div>)}</div><Button type="button" variant="secondary" onClick={() => setPoLines([...poLines, { drugId: "__none__", quantity: "", unitCost: "", taxRate: "0" }])}><Plus size={16} /> Add line</Button><Field label="Notes"><Textarea value={poForm.notes} onChange={(event) => setPoForm({ ...poForm, notes: event.target.value })} /></Field><Button type="submit" disabled={createPurchaseOrder.isPending}><ShoppingCart size={16} /> Draft purchase order</Button></form>}</Panel><Panel title="Receive batch stock" description="An expired batch is rejected. Capture batch number, expiry date, barcode, and warehouse at intake.">{!has("canStock") ? <SectionDenied>Your role cannot receive or create stock batches.</SectionDenied> : <form className="space-y-3" onSubmit={(event) => { event.preventDefault(); run(() => receiveStock.mutateAsync({ purchaseOrderId: receiptForm.purchaseOrderId === "__none__" ? undefined : receiptForm.purchaseOrderId, supplierId: receiptForm.supplierId, invoiceReference: receiptForm.invoiceReference, notes: receiptForm.notes, items: receiptLines.map((line) => ({ drugId: line.drugId, quantity: asNumber(line.quantity), unitCost: asNumber(line.unitCost), batchNumber: line.batchNumber, expiryDate: line.expiryDate, barcode: line.barcode, warehouse: line.warehouse })) }), "Stock receipt posted and supplier balance updated."); setReceiptForm({ purchaseOrderId: "__none__", supplierId: "__none__", invoiceReference: "", notes: "" }); setReceiptLines([EMPTY_RECEIPT_LINE]); }}><div className="grid gap-3 md:grid-cols-2"><Field label="Supplier"><Select required value={receiptForm.supplierId} onChange={(event) => setReceiptForm({ ...receiptForm, supplierId: event.target.value })}><option value="__none__">Select supplier</option>{suppliers.map((record) => <option key={record.id} value={record.id}>{record.name}</option>)}</Select></Field><Field label="Purchase order"><Select value={receiptForm.purchaseOrderId} onChange={(event) => setReceiptForm({ ...receiptForm, purchaseOrderId: event.target.value })}><option value="__none__">No linked purchase order</option>{orders.map((record) => <option key={record.id} value={record.id}>{record.name}</option>)}</Select></Field></div><Field label="Supplier invoice / GRN reference"><Input required value={receiptForm.invoiceReference} onChange={(event) => setReceiptForm({ ...receiptForm, invoiceReference: event.target.value })} /></Field><div className="space-y-2">{receiptLines.map((line, index) => <div key={index} className="grid gap-2 rounded-xl bg-slate-50 p-3 md:grid-cols-2"><Select required value={line.drugId} onChange={(event) => setReceiptLines(receiptLines.map((item, itemIndex) => itemIndex === index ? { ...item, drugId: event.target.value } : item))}><option value="__none__">Medicine</option>{medicines.map((record) => <option key={record.id} value={record.id}>{record.name}</option>)}</Select><Input required value={line.batchNumber} onChange={(event) => setReceiptLines(receiptLines.map((item, itemIndex) => itemIndex === index ? { ...item, batchNumber: event.target.value } : item))} placeholder="Batch / lot number" /><Input required min="0.0001" type="number" value={line.quantity} onChange={(event) => setReceiptLines(receiptLines.map((item, itemIndex) => itemIndex === index ? { ...item, quantity: event.target.value } : item))} placeholder="Quantity" /><Input required min="0" type="number" value={line.unitCost} onChange={(event) => setReceiptLines(receiptLines.map((item, itemIndex) => itemIndex === index ? { ...item, unitCost: event.target.value } : item))} placeholder="Unit cost" /><Input required type="date" value={line.expiryDate} onChange={(event) => setReceiptLines(receiptLines.map((item, itemIndex) => itemIndex === index ? { ...item, expiryDate: event.target.value } : item))} /><Input value={line.barcode} onChange={(event) => setReceiptLines(receiptLines.map((item, itemIndex) => itemIndex === index ? { ...item, barcode: event.target.value } : item))} placeholder="Batch barcode" /><Input value={line.warehouse} onChange={(event) => setReceiptLines(receiptLines.map((item, itemIndex) => itemIndex === index ? { ...item, warehouse: event.target.value } : item))} placeholder="Warehouse" />{receiptLines.length > 1 && <Button type="button" variant="secondary" onClick={() => setReceiptLines(receiptLines.filter((_, itemIndex) => itemIndex !== index))}><X size={16} /> Remove line</Button>}</div>)}</div><Button type="button" variant="secondary" onClick={() => setReceiptLines([...receiptLines, { ...EMPTY_RECEIPT_LINE }])}><Plus size={16} /> Add batch line</Button><Field label="Notes"><Textarea value={receiptForm.notes} onChange={(event) => setReceiptForm({ ...receiptForm, notes: event.target.value })} /></Field><Button type="submit" disabled={receiveStock.isPending}><PackageCheck size={16} /> Receive stock</Button></form>}</Panel></section><Panel title="Purchase orders" description="Draft orders and their protected totals are available to receiving staff.">{ordersQuery.isLoading ? <LoadingRows /> : orders.length ? <TableWrap><thead className="border-b text-xs uppercase tracking-wide text-slate-500"><tr><th className="pb-3 pr-3">Order</th><th className="pb-3 pr-3">Supplier</th><th className="pb-3 pr-3">Expected</th><th className="pb-3">Total</th></tr></thead><tbody>{orders.map((record) => <tr key={record.id} className="border-b border-slate-100"><td className="py-3 pr-3"><p className="font-semibold text-slate-900">{record.orderNo || record.name}</p><Status value={record.status} /></td><td className="py-3 pr-3">{record.supplierName || "—"}</td><td className="py-3 pr-3">{dateTime(record.expectedDate)}</td><td className="py-3 font-semibold">{money(record.total || record.amount)}</td></tr>)}</tbody></TableWrap> : <Empty>No purchase orders have been drafted.</Empty>}</Panel></div>}

    {tab === "Stock" && <div className="space-y-5"><section className="grid gap-5 xl:grid-cols-2"><Panel title="Batch inventory" description="Every batch shows its current FEFO eligibility, expiry, location, and quantity.">{batchesQuery.isLoading ? <LoadingRows /> : batches.length ? <TableWrap><thead className="border-b text-xs uppercase tracking-wide text-slate-500"><tr><th className="pb-3 pr-3">Medicine / batch</th><th className="pb-3 pr-3">Expiry</th><th className="pb-3 pr-3">Location</th><th className="pb-3">Available</th></tr></thead><tbody>{batches.map((record) => <tr key={record.id} className="border-b border-slate-100"><td className="py-3 pr-3"><p className="font-semibold text-slate-900">{record.drugName || record.name}</p><p className="text-xs text-slate-500">{record.batchNumber || "No batch"}</p></td><td className="py-3 pr-3"><span className={String(record.expiryDate || "") <= new Date(Date.now() + 90 * 86400000).toISOString().slice(0, 10) ? "font-semibold text-rose-700" : "text-slate-700"}>{dateOnly(record.expiryDate)}</span></td><td className="py-3 pr-3">{record.warehouse || "Main pharmacy"}</td><td className="py-3"><span className="font-semibold text-slate-900">{asNumber(record.quantityOnHand)}</span> <Status value={record.status} /></td></tr>)}</tbody></TableWrap> : <Empty>No batch stock is available. Use Purchasing to receive the first batch.</Empty>}</Panel><div className="space-y-5"><Panel title="Stock adjustment" description="A negative adjustment cannot make a batch quantity negative.">{!has("canStock") ? <SectionDenied>Stock adjustments are restricted for your role.</SectionDenied> : <form className="grid gap-3" onSubmit={(event) => { event.preventDefault(); run(() => adjustStock.mutateAsync({ ...adjustmentForm, quantityDelta: asNumber(adjustmentForm.quantityDelta) }), "Stock adjustment recorded."); setAdjustmentForm({ batchId: "__none__", quantityDelta: "", reason: "", notes: "" }); }}><Field label="Batch"><Select required value={adjustmentForm.batchId} onChange={(event) => setAdjustmentForm({ ...adjustmentForm, batchId: event.target.value })}><option value="__none__">Select batch</option>{batches.map((record) => <option key={record.id} value={record.id}>{record.drugName || record.name} · {record.batchNumber} · {asNumber(record.quantityOnHand)}</option>)}</Select></Field><Field label="Quantity change (+/-)"><Input required type="number" step="0.0001" value={adjustmentForm.quantityDelta} onChange={(event) => setAdjustmentForm({ ...adjustmentForm, quantityDelta: event.target.value })} /></Field><Field label="Reason"><Input required value={adjustmentForm.reason} onChange={(event) => setAdjustmentForm({ ...adjustmentForm, reason: event.target.value })} /></Field><Field label="Notes"><Textarea value={adjustmentForm.notes} onChange={(event) => setAdjustmentForm({ ...adjustmentForm, notes: event.target.value })} /></Field><Button type="submit" disabled={adjustStock.isPending}>Post adjustment</Button></form>}</Panel><Panel title="Stock transfer" description="A transfer request cannot exceed the available source-batch quantity.">{!has("canStock") ? <SectionDenied>Stock transfer requests are restricted for your role.</SectionDenied> : <form className="grid gap-3" onSubmit={(event) => { event.preventDefault(); run(() => createTransfer.mutateAsync({ ...transferForm, quantity: asNumber(transferForm.quantity) }), "Stock transfer requested."); setTransferForm({ batchId: "__none__", quantity: "", fromLocation: "Main pharmacy", toLocation: "", notes: "" }); }}><Field label="Batch"><Select required value={transferForm.batchId} onChange={(event) => setTransferForm({ ...transferForm, batchId: event.target.value })}><option value="__none__">Select batch</option>{batches.map((record) => <option key={record.id} value={record.id}>{record.drugName || record.name} · {record.batchNumber}</option>)}</Select></Field><Field label="Quantity"><Input required min="0.0001" type="number" value={transferForm.quantity} onChange={(event) => setTransferForm({ ...transferForm, quantity: event.target.value })} /></Field><Field label="From"><Input required value={transferForm.fromLocation} onChange={(event) => setTransferForm({ ...transferForm, fromLocation: event.target.value })} /></Field><Field label="To"><Input required value={transferForm.toLocation} onChange={(event) => setTransferForm({ ...transferForm, toLocation: event.target.value })} /></Field><Button type="submit" disabled={createTransfer.isPending}><ArrowRightLeft size={16} /> Request transfer</Button></form>}</Panel></div></section><section className="grid gap-5 xl:grid-cols-2"><Panel title="Recent stock movements" description="Receipts, adjustments, FEFO issues, sales, and eligible returns form the batch movement history.">{movementsQuery.isLoading ? <LoadingRows /> : movements.length ? <div className="space-y-2">{movements.slice(0, 12).map((record) => <div key={record.id} className="flex items-center justify-between rounded-xl bg-slate-50 p-3"><div><p className="font-semibold text-slate-900">{record.name}</p><p className="text-xs text-slate-500">{dateTime(record.occurredAt)}</p></div><span className={`font-bold ${asNumber(record.quantityDelta) < 0 ? "text-rose-700" : "text-emerald-700"}`}>{asNumber(record.quantityDelta) > 0 ? "+" : ""}{asNumber(record.quantityDelta)}</span></div>)}</div> : <Empty>No stock movement has been recorded.</Empty>}</Panel><Panel title="Transfer queue" description="Operational transfer requests remain visible and auditable.">{transfersQuery.isLoading ? <LoadingRows /> : transfers.length ? <div className="space-y-2">{transfers.map((record) => <div key={record.id} className="rounded-xl border border-slate-200 p-3"><div className="flex items-center justify-between gap-3"><p className="font-semibold text-slate-900">{record.drugName || record.name}</p><Status value={record.status} /></div><p className="mt-1 text-sm text-slate-600">{record.quantity} from {record.fromLocation} to {record.toLocation}</p></div>)}</div> : <Empty>No transfer requests are awaiting handling.</Empty>}</Panel></section></div>}

    {tab === "Dispensing" && <div className="space-y-5"><section className="grid gap-5 xl:grid-cols-[1.2fr_0.8fr]"><Panel title="Dispense prescription" description="Prescription-only and controlled medicines are blocked unless a valid clinical reference is selected.">{!has("canDispense") ? <SectionDenied>Your role cannot issue medicines from the dispensary.</SectionDenied> : <form className="space-y-3" onSubmit={(event) => { event.preventDefault(); run(() => dispensePrescription.mutateAsync({ patientId: dispenseForm.patientId, prescriptionId: dispenseForm.prescriptionId === "__manual__" ? undefined : dispenseForm.prescriptionId, prescriberName: dispenseForm.prescriberName, prescriberLicense: dispenseForm.prescriberLicense, notes: dispenseForm.notes, items: dispenseLines.map((line) => ({ drugId: line.drugId, quantity: asNumber(line.quantity), instructions: line.instructions })) }), "Prescription dispensed using eligible FEFO batches."); setDispenseForm({ prescriptionId: "__manual__", patientId: "__none__", prescriberName: "", prescriberLicense: "", notes: "" }); setDispenseLines([EMPTY_DISPENSE_LINE]); }}><div className="grid gap-3 md:grid-cols-2"><Field label="Clinical prescription"><Select value={dispenseForm.prescriptionId} onChange={(event) => event.target.value === "__manual__" ? setDispenseForm({ ...dispenseForm, prescriptionId: "__manual__" }) : choosePrescription(event.target.value)}><option value="__manual__">Manual clinical reference</option>{asList(clinical.prescriptions).map((record) => <option key={record.id} value={record.id}>{record.patientName || record.name} · {record.doctorName || "Prescriber"}</option>)}</Select></Field><Field label="Patient"><Select required value={dispenseForm.patientId} onChange={(event) => setDispenseForm({ ...dispenseForm, patientId: event.target.value })}><option value="__none__">Select patient</option>{asList(clinical.patients).map((record) => <option key={record.id} value={record.id}>{record.name}{record.mrn ? ` · ${record.mrn}` : ""}</option>)}</Select></Field><Field label="Prescriber"><Input required value={dispenseForm.prescriberName} onChange={(event) => setDispenseForm({ ...dispenseForm, prescriberName: event.target.value })} /></Field><Field label="Prescriber licence"><Input value={dispenseForm.prescriberLicense} onChange={(event) => setDispenseForm({ ...dispenseForm, prescriberLicense: event.target.value })} /></Field></div><div className="space-y-2">{dispenseLines.map((line, index) => <div key={index} className="grid gap-2 rounded-xl bg-slate-50 p-3 md:grid-cols-[1.6fr_0.6fr_1.3fr_auto]"><Select required value={line.drugId} onChange={(event) => setDispenseLines(dispenseLines.map((item, itemIndex) => itemIndex === index ? { ...item, drugId: event.target.value } : item))}><option value="__none__">Medicine</option>{medicines.map((record) => <option key={record.id} value={record.id}>{record.name}{record.controlled ? " · Controlled" : record.requiresPrescription ? " · Rx" : ""}</option>)}</Select><Input required min="0.0001" type="number" value={line.quantity} onChange={(event) => setDispenseLines(dispenseLines.map((item, itemIndex) => itemIndex === index ? { ...item, quantity: event.target.value } : item))} placeholder="Qty" /><Input value={line.instructions} onChange={(event) => setDispenseLines(dispenseLines.map((item, itemIndex) => itemIndex === index ? { ...item, instructions: event.target.value } : item))} placeholder="Patient directions" />{dispenseLines.length > 1 && <Button type="button" variant="secondary" onClick={() => setDispenseLines(dispenseLines.filter((_, itemIndex) => itemIndex !== index))}><X size={16} /></Button>}</div>)}</div><Button type="button" variant="secondary" onClick={() => setDispenseLines([...dispenseLines, { ...EMPTY_DISPENSE_LINE }])}><Plus size={16} /> Add medicine</Button><Field label="Dispensing notes"><Textarea value={dispenseForm.notes} onChange={(event) => setDispenseForm({ ...dispenseForm, notes: event.target.value })} /></Field><Button type="submit" disabled={dispensePrescription.isPending}><ScanLine size={16} /> Dispense prescription</Button></form>}</Panel><Panel title="Clinical prescription queue" description="Only pending or partial prescriptions from this workspace are exposed to the dispensary.">{clinicalQuery.isLoading ? <LoadingRows /> : asList(clinical.prescriptions).length ? <div className="space-y-2">{asList(clinical.prescriptions).map((record) => <button key={record.id} className="w-full rounded-xl border border-slate-200 p-3 text-left transition hover:border-emerald-300 hover:bg-emerald-50" onClick={() => choosePrescription(record.id)}><div className="flex items-center justify-between gap-2"><p className="font-semibold text-slate-900">{record.patientName || record.name}</p><Status value={record.status} /></div><p className="mt-1 text-xs text-slate-600">{record.doctorName || "Prescriber not named"} · {dateTime(record.issuedAt)}</p><p className="mt-2 text-xs text-slate-500">{asList(record.medications).map((item) => item?.name).filter(Boolean).join(", ") || "No medicine lines available"}</p></button>)}</div> : <Empty>No pending prescriptions are available for dispensing.</Empty>}</Panel></section><section className="grid gap-5 xl:grid-cols-2"><Panel title="Recent dispensings" description="Dispensing records retain the clinical reference and FEFO allocation evidence.">{dispensesQuery.isLoading ? <LoadingRows /> : dispenses.length ? <div className="space-y-2">{dispenses.slice(0, 12).map((record) => <div key={record.id} className="rounded-xl bg-slate-50 p-3"><div className="flex items-center justify-between"><p className="font-semibold text-slate-900">{record.dispenseNo || record.name}</p><Status value={record.status} /></div><p className="mt-1 text-sm text-slate-600">{record.patientName || "Patient"} · {money(record.total || record.amount)}</p></div>)}</div> : <Empty>No prescription has been dispensed.</Empty>}</Panel><Panel title="Controlled-medicine register" description="Only authorised pharmacist or pharmacy-administrator activity can issue controlled medicines.">{controlledQuery.isLoading ? <LoadingRows /> : controlled.length ? <div className="space-y-2">{controlled.slice(0, 12).map((record) => <div key={record.id} className="rounded-xl border border-amber-200 bg-amber-50 p-3"><div className="flex justify-between gap-2"><p className="font-semibold text-slate-900">{record.name}</p><Status value={record.status} /></div><p className="mt-1 text-xs text-slate-600">Patient reference recorded · Quantity {record.quantity}</p></div>)}</div> : <Empty>No controlled-medicine issue has been recorded.</Empty>}</Panel></section></div>}

    {tab === "POS" && <div className="space-y-5"><section className="grid gap-5 xl:grid-cols-2"><Panel title="Counter sale / receipt" description="Prescription-only and controlled medicines are rejected at the protected counter-sale boundary.">{!has("canSale") ? <SectionDenied>Your role cannot complete counter sales.</SectionDenied> : <form className="space-y-3" onSubmit={(event) => { event.preventDefault(); run(() => completeSale.mutateAsync({ patientId: saleForm.patientId === "__none__" ? undefined : saleForm.patientId, customerName: saleForm.customerName, paymentMethod: saleForm.paymentMethod, insuranceProvider: saleForm.insuranceProvider, discount: asNumber(saleForm.discount), notes: saleForm.notes, items: saleLines.map((line) => ({ drugId: line.drugId, quantity: asNumber(line.quantity) })) }), "Sale completed and receipt number recorded."); setSaleForm({ patientId: "__none__", customerName: "", paymentMethod: "Cash", insuranceProvider: "", discount: "0", notes: "" }); setSaleLines([EMPTY_POS_LINE]); }}><div className="grid gap-3 md:grid-cols-2"><Field label="Customer"><Input value={saleForm.customerName} onChange={(event) => setSaleForm({ ...saleForm, customerName: event.target.value })} placeholder="Walk-in customer" /></Field><Field label="Patient (optional)"><Select value={saleForm.patientId} onChange={(event) => setSaleForm({ ...saleForm, patientId: event.target.value })}><option value="__none__">No patient linked</option>{asList(clinical.patients).map((record) => <option key={record.id} value={record.id}>{record.name}</option>)}</Select></Field><Field label="Payment method"><Select value={saleForm.paymentMethod} onChange={(event) => setSaleForm({ ...saleForm, paymentMethod: event.target.value })}>{["Cash", "Mobile money", "Card", "Insurance", "Credit"].map((value) => <option key={value}>{value}</option>)}</Select></Field><Field label="Insurance provider"><Input value={saleForm.insuranceProvider} disabled={saleForm.paymentMethod !== "Insurance"} onChange={(event) => setSaleForm({ ...saleForm, insuranceProvider: event.target.value })} /></Field><Field label="Discount (TZS)"><Input min="0" type="number" value={saleForm.discount} onChange={(event) => setSaleForm({ ...saleForm, discount: event.target.value })} /></Field></div><div className="space-y-2">{saleLines.map((line, index) => <div key={index} className="grid gap-2 rounded-xl bg-slate-50 p-3 md:grid-cols-[1.7fr_0.7fr_auto]"><Select required value={line.drugId} onChange={(event) => setSaleLines(saleLines.map((item, itemIndex) => itemIndex === index ? { ...item, drugId: event.target.value } : item))}><option value="__none__">Counter-sale medicine</option>{medicines.filter((record) => !record.requiresPrescription && !record.controlled).map((record) => <option key={record.id} value={record.id}>{record.name} · {money(record.sellingPrice || record.amount)} · {asNumber(record.availableQuantity)} available</option>)}</Select><Input required min="0.0001" type="number" value={line.quantity} onChange={(event) => setSaleLines(saleLines.map((item, itemIndex) => itemIndex === index ? { ...item, quantity: event.target.value } : item))} />{saleLines.length > 1 && <Button type="button" variant="secondary" onClick={() => setSaleLines(saleLines.filter((_, itemIndex) => itemIndex !== index))}><X size={16} /></Button>}</div>)}</div><Button type="button" variant="secondary" onClick={() => setSaleLines([...saleLines, { ...EMPTY_POS_LINE }])}><Plus size={16} /> Add line</Button><Field label="Receipt notes"><Textarea value={saleForm.notes} onChange={(event) => setSaleForm({ ...saleForm, notes: event.target.value })} /></Field><Button type="submit" disabled={completeSale.isPending}><ReceiptText size={16} /> Complete sale</Button></form>}</Panel><div className="space-y-5"><Panel title="Record sale settlement" description="Partial settlement remains payable until the recorded sale balance reaches zero.">{!has("canFinance") ? <SectionDenied>Settlement recording is limited to pharmacy finance roles.</SectionDenied> : <form className="grid gap-3" onSubmit={(event) => { event.preventDefault(); run(() => recordSalePayment.mutateAsync({ ...salePayment, amount: asNumber(salePayment.amount) }), "Sale settlement recorded."); setSalePayment({ saleId: "__none__", amount: "", method: "Cash", insuranceProvider: "", reference: "", notes: "" }); }}><Field label="Sale / receipt"><Select required value={salePayment.saleId} onChange={(event) => setSalePayment({ ...salePayment, saleId: event.target.value })}><option value="__none__">Select sale</option>{sales.filter((record) => !/paid/i.test(record.status)).map((record) => <option key={record.id} value={record.id}>{record.receiptNo || record.name} · {money(record.total || record.amount)}</option>)}</Select></Field><Field label="Amount (TZS)"><Input required min="1" type="number" value={salePayment.amount} onChange={(event) => setSalePayment({ ...salePayment, amount: event.target.value })} /></Field><Field label="Method"><Select value={salePayment.method} onChange={(event) => setSalePayment({ ...salePayment, method: event.target.value })}>{["Cash", "Mobile money", "Card", "Bank transfer", "Insurance"].map((value) => <option key={value}>{value}</option>)}</Select></Field><Field label="Reference"><Input value={salePayment.reference} onChange={(event) => setSalePayment({ ...salePayment, reference: event.target.value })} /></Field><Button type="submit" disabled={recordSalePayment.isPending}>Record settlement</Button></form>}</Panel><Panel title="Submit insurance claim" description="Claims are capped at the selected sale’s unsettled balance.">{!has("canFinance") ? <SectionDenied>Insurance claims are limited to pharmacy finance roles.</SectionDenied> : <form className="grid gap-3" onSubmit={(event) => { event.preventDefault(); run(() => createInsuranceClaim.mutateAsync({ ...insuranceClaim, amount: asNumber(insuranceClaim.amount) }), "Insurance claim submitted."); setInsuranceClaim({ saleId: "__none__", provider: "", memberReference: "", amount: "", notes: "" }); }}><Field label="Sale"><Select required value={insuranceClaim.saleId} onChange={(event) => setInsuranceClaim({ ...insuranceClaim, saleId: event.target.value })}><option value="__none__">Select sale</option>{sales.filter((record) => !/paid/i.test(record.status)).map((record) => <option key={record.id} value={record.id}>{record.receiptNo || record.name}</option>)}</Select></Field><Field label="Insurer"><Input required value={insuranceClaim.provider} onChange={(event) => setInsuranceClaim({ ...insuranceClaim, provider: event.target.value })} /></Field><Field label="Member reference"><Input value={insuranceClaim.memberReference} onChange={(event) => setInsuranceClaim({ ...insuranceClaim, memberReference: event.target.value })} /></Field><Field label="Claim amount (TZS)"><Input required min="1" type="number" value={insuranceClaim.amount} onChange={(event) => setInsuranceClaim({ ...insuranceClaim, amount: event.target.value })} /></Field><Button type="submit" disabled={createInsuranceClaim.isPending}>Submit claim</Button></form>}</Panel></div></section><section className="grid gap-5 xl:grid-cols-2"><Panel title="Sale returns" description="Only original sale lines can be returned. Sealed, unexpired goods are eligible for batch restock.">{!has("canSale") ? <SectionDenied>Returns require counter-sale authority.</SectionDenied> : <form className="space-y-3" onSubmit={(event) => { event.preventDefault(); run(() => returnSaleItems.mutateAsync({ saleId: returnForm.saleId, reason: returnForm.reason, condition: returnForm.condition, notes: returnForm.notes, items: returnLines.map((line) => ({ saleItemId: line.saleItemId, quantity: asNumber(line.quantity) })) }), "Return recorded with batch-restock safeguards."); setReturnForm({ saleId: "__none__", reason: "", condition: "Sealed and resellable", notes: "" }); setReturnLines([]); }}><Field label="Original sale"><Select required value={returnForm.saleId} onChange={(event) => { const value = event.target.value; setReturnForm({ ...returnForm, saleId: value }); setReturnLines([]); }}><option value="__none__">Select sale</option>{sales.map((record) => <option key={record.id} value={record.id}>{record.receiptNo || record.name} · {record.customerName || "Customer"}</option>)}</Select></Field>{selectedReturnItems.length ? <div className="space-y-2">{selectedReturnItems.map((record) => { const line = returnLines.find((item) => item.saleItemId === record.id); return <div key={record.id} className="flex items-center justify-between gap-3 rounded-xl bg-slate-50 p-3"><div><p className="font-semibold text-slate-900">{record.drugName || record.name}</p><p className="text-xs text-slate-500">Available to return: {asNumber(record.quantity) - asNumber(record.returnedQuantity)}</p></div><Input className="w-24" min="0" max={asNumber(record.quantity) - asNumber(record.returnedQuantity)} type="number" value={line?.quantity || ""} onChange={(event) => { const next = event.target.value; setReturnLines(next ? [...returnLines.filter((item) => item.saleItemId !== record.id), { saleItemId: record.id, quantity: next }] : returnLines.filter((item) => item.saleItemId !== record.id)); }} /></div>; })}</div> : returnForm.saleId !== "__none__" && <Empty>No returnable sale lines remain for this receipt.</Empty>}<Field label="Condition"><Select value={returnForm.condition} onChange={(event) => setReturnForm({ ...returnForm, condition: event.target.value })}>{["Sealed and resellable", "Damaged", "Expired", "Unknown"].map((value) => <option key={value}>{value}</option>)}</Select></Field><Field label="Reason"><Input required value={returnForm.reason} onChange={(event) => setReturnForm({ ...returnForm, reason: event.target.value })} /></Field><Field label="Notes"><Textarea value={returnForm.notes} onChange={(event) => setReturnForm({ ...returnForm, notes: event.target.value })} /></Field><Button type="submit" disabled={returnSaleItems.isPending || !returnLines.length}>Record return</Button></form>}</Panel><Panel title="Receipts and claims" description="Every retail sale, return, and insurer claim remains visible in the pharmacy record.">{salesQuery.isLoading ? <LoadingRows /> : sales.length ? <div className="space-y-2">{sales.slice(0, 10).map((record) => <div key={record.id} className="rounded-xl border border-slate-200 p-3"><div className="flex items-center justify-between gap-2"><p className="font-semibold text-slate-900">{record.receiptNo || record.name}</p><Status value={record.status} /></div><p className="mt-1 text-sm text-slate-600">{record.customerName || "Walk-in customer"} · {money(record.total || record.amount)}</p></div>)}</div> : <Empty>No retail sale has been completed.</Empty>}<div className="mt-4 border-t pt-4"><p className="mb-2 text-sm font-semibold text-slate-900">Insurance claims</p>{claims.length ? claims.slice(0, 5).map((record) => <div key={record.id} className="mb-2 flex justify-between rounded-lg bg-slate-50 p-2 text-sm"><span>{record.claimNo || record.name} · {record.provider}</span><Status value={record.status} /></div>) : <p className="text-sm text-slate-500">No pharmacy insurance claim is recorded.</p>}</div></Panel></section></div>}

    {tab === "Reports" && <div className="space-y-5"><section className="grid gap-3 md:grid-cols-3">{reportsQuery.isLoading ? <div className="md:col-span-3"><LoadingRows /></div> : <><article className="rounded-2xl border border-slate-200 bg-white p-5"><p className="text-xs font-bold uppercase tracking-wide text-slate-500">Inventory value</p><p className="mt-2 text-2xl font-bold text-slate-900">{money(reportsQuery.data?.stock?.stockValue)}</p><p className="mt-1 text-sm text-slate-500">{asNumber(reportsQuery.data?.stock?.activeBatchCount)} active batches</p></article><article className="rounded-2xl border border-slate-200 bg-white p-5"><p className="text-xs font-bold uppercase tracking-wide text-slate-500">Supplier payables</p><p className="mt-2 text-2xl font-bold text-slate-900">{money(reportsQuery.data?.finance?.supplierBalance)}</p><p className="mt-1 text-sm text-slate-500">Receivables: {money(reportsQuery.data?.finance?.receivables)}</p></article><article className="rounded-2xl border border-slate-200 bg-white p-5"><p className="text-xs font-bold uppercase tracking-wide text-slate-500">Controlled issues</p><p className="mt-2 text-2xl font-bold text-slate-900">{asNumber(reportsQuery.data?.compliance?.controlledIssues)}</p><p className="mt-1 text-sm text-slate-500">Insurance claims: {asNumber(reportsQuery.data?.compliance?.insuranceClaims)}</p></article></>}</section><section className="grid gap-5 xl:grid-cols-2"><Panel title="Financial and stock report" description="Live tenant-scoped totals for finance reconciliation and inventory oversight.">{reportsQuery.data && <div className="space-y-3">{[["Sales value", reportsQuery.data.finance.salesTotal], ["Cash / settlement received", reportsQuery.data.finance.cashReceived], ["Returns value", reportsQuery.data.finance.returnValue], ["Stock movements", reportsQuery.data.stock.movements]].map(([label, value]) => <div key={label} className="flex justify-between rounded-xl bg-slate-50 p-3"><span className="text-sm font-semibold text-slate-700">{label}</span><span className="font-bold text-slate-900">{label === "Stock movements" ? asNumber(value) : money(value)}</span></div>)}</div>}</Panel><Panel title="Controlled-medicine report" description="The register is available to authorised pharmacy governance roles.">{controlled.length ? <TableWrap><thead className="border-b text-xs uppercase tracking-wide text-slate-500"><tr><th className="pb-3 pr-3">Issue</th><th className="pb-3 pr-3">Quantity</th><th className="pb-3">Status</th></tr></thead><tbody>{controlled.map((record) => <tr key={record.id} className="border-b border-slate-100"><td className="py-3 pr-3"><p className="font-semibold text-slate-900">{record.name}</p><p className="text-xs text-slate-500">{dateTime(record.issuedAt)}</p></td><td className="py-3 pr-3">{record.quantity}</td><td className="py-3"><Status value={record.status} /></td></tr>)}</tbody></TableWrap> : <Empty>No controlled-medicine issue is in this reporting period.</Empty>}</Panel></section><Panel title="Pharmacy audit history" description="Immutable action records are shown only to pharmacy governance roles.">{!has("canGovern") ? <SectionDenied>Audit visibility is restricted to pharmacy governance roles.</SectionDenied> : auditQuery.isLoading ? <LoadingRows /> : asList(auditQuery.data).length ? <div className="space-y-2">{asList(auditQuery.data).slice(0, 30).map((record) => <div key={record.id} className="flex flex-col justify-between gap-2 rounded-xl border border-slate-200 p-3 md:flex-row md:items-center"><div><p className="font-semibold text-slate-900">{record.action || record.name}</p><p className="text-xs text-slate-500">{record.entity || "Pharmacy record"} · {dateTime(record.recordedAt || record.created_at)}</p></div><Status value={record.status} /></div>)}</div> : <Empty>No pharmacy audit event has been recorded.</Empty>}</Panel></div>}

    {tab === "Alerts & audit" && <div className="grid gap-5 xl:grid-cols-2"><Panel title="Pharmacy notifications" description="Low-stock, expiry, and return exceptions remain visible until an authorised user marks them read.">{data.notifications.length ? <div className="space-y-3">{data.notifications.map((record) => <div key={record.id} className="rounded-xl border border-slate-200 p-4"><div className="flex items-start justify-between gap-3"><div><p className="font-semibold text-slate-900">{record.name}</p><p className="mt-1 text-sm text-slate-600">{record.reason || record.message || "Review this pharmacy exception."}</p><p className="mt-1 text-xs text-slate-500">{dateTime(record.createdAt || record.created_at)}</p></div><div className="flex flex-col items-end gap-2"><Status value={record.severity || record.status} /><Button variant="secondary" disabled={markNotificationRead.isPending} onClick={() => run(() => markNotificationRead.mutateAsync({ id: record.id }), "Notification marked as read.")}>Mark read</Button></div></div></div>)}</div> : <Empty>No unread Pharmacy notification requires attention.</Empty>}</Panel><Panel title="Operational recovery" description="Use the relevant workflow to correct an exception; the system retains the original record and audit history."><div className="space-y-3"><div className="rounded-xl bg-amber-50 p-4 text-sm text-amber-900"><AlertTriangle size={18} className="mb-2" /><strong>Low stock or expiry risk.</strong> Create a purchase order or safely adjust/transfer a batch from the Stock workspace.</div><div className="rounded-xl bg-rose-50 p-4 text-sm text-rose-900"><FileClock size={18} className="mb-2" /><strong>Clinical or controlled-medicine exception.</strong> Verify the prescription and prescriber data before re-attempting dispensing.</div><div className="rounded-xl bg-indigo-50 p-4 text-sm text-indigo-900"><CheckCircle2 size={18} className="mb-2" /><strong>Finance exception.</strong> Record an eligible sale, supplier settlement, insurer claim, or return rather than editing a historical total.</div></div></Panel></div>}
  </div>;
}
